const items = $input.all();
for (const item of items) {
  const txt = item.json.response || '';
  let score = 10, issues = [], priority = 'Low', recs = '';
  try {
    const s = txt.match(/score.*?(\d+)/i); if (s) score = +s[1];
    const iss = txt.match(/detected issues[\s\S]*?(?=\n\n|$)/i);
    if (iss) issues = iss[0].split('\n').map(l => l.trim()).filter(l => l && !l.toLowerCase().includes('detected issues'));
    const p = txt.match(/priority.*?([High|Medium|Low]+)/i); if (p) priority = p[1].trim();
    const r = txt.match(/recommendations[\s\S]*$/i); if (r) recs = r[0].replace(/recommendations[:\s]*/i, '').trim();
  } catch(e){}
  item.json.score = score;
  item.json.issues = issues;
  item.json.priority = priority;
  item.json.recommendations = recs;
  item.json.aiResponse = txt;
}
return items;
